/* 한글 문서(hwpx) 만들기 — 한글 2024가 저장한 견본의 머리(header.xml)를 틀로 쓴다.
   Hwpx.photoDoc(docs) → Uint8Array (zip)
   docs: [{ sub, title, info: [[라벨, 값, 라벨, 값] | [라벨, 값(가로 전체)]], pages: [{ cols, rows, photos: [{ bytes, ext, w, h, caption }] }],
            items: { head: [...], rows: [[...]] } | null, foot }] */
const Hwpx = (() => {
  const MM = 283.465;
  const u = mm => Math.round(mm * MM);
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  let seq = 1000000;
  const id = () => String(++seq);

  /* 서식 번호 (HEADER에 더한 것) */
  const CP = { normal: 0, title: 7, sub: 8, label: 9, text: 10, cap: 11, foot: 12 };
  const PP = { left: 0, center: 20, right: 21, pic: 22 };
  const BF = { line: 3, gray: 4 };

  const para = (txt, pp, cp, extra) => `<hp:p id="${extra && extra.pid || '0'}" paraPrIDRef="${pp}" styleIDRef="0" pageBreak="${extra && extra.pageBreak ? 1 : 0}" columnBreak="0" merged="0">${extra && extra.pre || ''}<hp:run charPrIDRef="${cp}"><hp:t>${esc(txt)}</hp:t></hp:run></hp:p>`;
  const sub = (inner, va) => `<hp:subList id="" textDirection="HORIZONTAL" lineWrap="BREAK" vertAlign="${va || 'CENTER'}" linkListIDRef="0" linkListNextIDRef="0" textWidth="0" textHeight="0" hasTextRef="0" hasNumRef="0">${inner}</hp:subList>`;
  const cell = (c, r, w, h, inner, bf, cs, rs) => `<hp:tc name="" header="0" hasMargin="0" protect="0" editable="0" dirty="0" borderFillIDRef="${bf || BF.line}">${sub(inner)}<hp:cellAddr colAddr="${c}" rowAddr="${r}"/><hp:cellSpan colSpan="${cs || 1}" rowSpan="${rs || 1}"/><hp:cellSz width="${w}" height="${h}"/><hp:cellMargin left="425" right="425" top="85" bottom="85"/></hp:tc>`;
  /* rows: [[{ w, inner, bf, cs, rs }]] , 행 높이 hs[]. rs(세로 병합)가 있으면 아래 줄들은 그 칸을 빼고 적는다 */
  /* opt.flow: 글자처럼 취급 끄고 문단에 붙임 → 긴 표가 쪽 경계에서 셀 단위로 나뉘고 머리글이 반복됨 (textDoc이 씀. 사진 문서는 기본) */
  function table(rows, hs, colCnt, opt){
    const W = rows[0].reduce((a, c) => a + c.w, 0), flow = !!(opt && opt.flow), H = Math.min(hs.reduce((a, b) => a + b, 0), flow ? u(240) : Infinity);   // 쪽을 넘는 긴 표는 한글이 나누므로 전체 높이는 한 쪽 안으로 (실제 문서도 첫 쪽 분량만 적혀 있음)
    const busy = {};   // 위 줄의 세로 병합이 차지한 칸: 열 → 남은 줄 수
    let x = `<hp:tbl id="${id()}" zOrder="0" numberingType="TABLE" textWrap="TOP_AND_BOTTOM" textFlow="BOTH_SIDES" lock="0" dropcapstyle="None" pageBreak="CELL" repeatHeader="${flow ? 1 : 0}" rowCnt="${rows.length}" colCnt="${colCnt}" cellSpacing="0" borderFillIDRef="${BF.line}" noAdjust="0">`
      + `<hp:sz width="${W}" widthRelTo="ABSOLUTE" height="${H}" heightRelTo="ABSOLUTE" protect="0"/>`
      + `<hp:pos treatAsChar="${flow ? 0 : 1}" affectLSpacing="0" flowWithText="1" allowOverlap="0" holdAnchorAndSO="0" vertRelTo="PARA" horzRelTo="${flow ? 'PARA' : 'COLUMN'}" vertAlign="TOP" horzAlign="LEFT" vertOffset="0" horzOffset="0"/>`
      + `<hp:outMargin left="0" right="0" top="0" bottom="0"/><hp:inMargin left="425" right="425" top="85" bottom="85"/>`;
    rows.forEach((row, r) => {
      x += '<hp:tr>'; let c = 0;
      row.forEach(cl => {
        while (busy[c] > 0) c++;
        const rs = cl.rs > 1 ? cl.rs : 1, h = rs > 1 ? hs.slice(r, r + rs).reduce((a, b) => a + b, 0) : hs[r];
        x += cell(c, r, cl.w, h, cl.inner, cl.bf, cl.cs, rs);
        if (rs > 1) for (let k = 0; k < (cl.cs || 1); k++) busy[c + k] = rs;
        c += cl.cs || 1;
      });
      Object.keys(busy).forEach(k => { if (busy[k] > 0) busy[k]--; });
      x += '</hp:tr>';
    });
    return x + '</hp:tbl>';
  }
  const tablePara = (tbl, extra) => `<hp:p id="0" paraPrIDRef="${PP.center}" styleIDRef="0" pageBreak="${extra && extra.pageBreak ? 1 : 0}" columnBreak="0" merged="0">${extra && extra.pre || ''}<hp:run charPrIDRef="0">${tbl}<hp:t/></hp:run></hp:p>`;
  function pic(bin, wPx, hPx, W, H){
    const dw = wPx * 75, dh = hPx * 75;
    return `<hp:pic id="${id()}" zOrder="1" numberingType="PICTURE" textWrap="TOP_AND_BOTTOM" textFlow="BOTH_SIDES" lock="0" dropcapstyle="None" href="" groupLevel="0" instid="${id()}" reverse="0">`
      + `<hp:offset x="0" y="0"/><hp:orgSz width="${W}" height="${H}"/><hp:curSz width="${W}" height="${H}"/><hp:flip horizontal="0" vertical="0"/>`
      + `<hp:rotationInfo angle="0" centerX="${W >> 1}" centerY="${H >> 1}" rotateimage="1"/>`
      + `<hp:renderingInfo><hc:transMatrix e1="1" e2="0" e3="0" e4="0" e5="1" e6="0"/><hc:scaMatrix e1="1" e2="0" e3="0" e4="0" e5="1" e6="0"/><hc:rotMatrix e1="1" e2="0" e3="0" e4="0" e5="1" e6="0"/></hp:renderingInfo>`
      + `<hc:img binaryItemIDRef="${bin}" bright="0" contrast="0" effect="REAL_PIC" alpha="0"/>`
      + `<hp:imgRect><hc:pt0 x="0" y="0"/><hc:pt1 x="${W}" y="0"/><hc:pt2 x="${W}" y="${H}"/><hc:pt3 x="0" y="${H}"/></hp:imgRect>`
      + `<hp:imgClip left="0" right="${dw}" top="0" bottom="${dh}"/><hp:inMargin left="0" right="0" top="0" bottom="0"/><hp:imgDim dimwidth="${dw}" dimheight="${dh}"/><hp:effects/>`
      + `<hp:sz width="${W}" widthRelTo="ABSOLUTE" height="${H}" heightRelTo="ABSOLUTE" protect="0"/>`
      + `<hp:pos treatAsChar="1" affectLSpacing="0" flowWithText="1" allowOverlap="0" holdAnchorAndSO="0" vertRelTo="PARA" horzRelTo="COLUMN" vertAlign="TOP" horzAlign="LEFT" vertOffset="0" horzOffset="0"/>`
      + `<hp:outMargin left="0" right="0" top="0" bottom="0"/><hp:shapeComment>그림입니다.</hp:shapeComment></hp:pic>`;
  }
  const SECPR = `<hp:run charPrIDRef="0"><hp:secPr id="" textDirection="HORIZONTAL" spaceColumns="1134" tabStop="8000" tabStopVal="4000" tabStopUnit="HWPUNIT" outlineShapeIDRef="1" memoShapeIDRef="0" textVerticalWidthHead="0" masterPageCnt="0"><hp:grid lineGrid="0" charGrid="0" wonggojiFormat="0"/><hp:startNum pageStartsOn="BOTH" page="0" pic="0" tbl="0" equation="0"/><hp:visibility hideFirstHeader="0" hideFirstFooter="0" hideFirstMasterPage="0" border="SHOW_ALL" fill="SHOW_ALL" hideFirstPageNum="0" hideFirstEmptyLine="0" showLineNumber="0"/><hp:lineNumberShape restartType="0" countBy="0" distance="0" startNumber="0"/><hp:pagePr landscape="WIDELY" width="59528" height="84186" gutterType="LEFT_ONLY"><hp:margin header="0" footer="0" gutter="0" left="${u(20)}" right="${u(20)}" top="${u(15)}" bottom="${u(12)}"/></hp:pagePr><hp:footNotePr><hp:autoNumFormat type="DIGIT" userChar="" prefixChar="" suffixChar=")" supscript="0"/><hp:noteLine length="-1" type="SOLID" width="0.12 mm" color="#000000"/><hp:noteSpacing betweenNotes="283" belowLine="567" aboveLine="850"/><hp:numbering type="CONTINUOUS" newNum="1"/><hp:placement place="EACH_COLUMN" beneathText="0"/></hp:footNotePr><hp:endNotePr><hp:autoNumFormat type="DIGIT" userChar="" prefixChar="" suffixChar=")" supscript="0"/><hp:noteLine length="14692344" type="SOLID" width="0.12 mm" color="#000000"/><hp:noteSpacing betweenNotes="0" belowLine="567" aboveLine="850"/><hp:numbering type="CONTINUOUS" newNum="1"/><hp:placement place="END_OF_DOCUMENT" beneathText="0"/></hp:endNotePr><hp:pageBorderFill type="BOTH" borderFillIDRef="1" textBorder="PAPER" headerInside="0" footerInside="0" fillArea="PAPER"><hp:offset left="1417" right="1417" top="1417" bottom="1417"/></hp:pageBorderFill><hp:pageBorderFill type="EVEN" borderFillIDRef="1" textBorder="PAPER" headerInside="0" footerInside="0" fillArea="PAPER"><hp:offset left="1417" right="1417" top="1417" bottom="1417"/></hp:pageBorderFill><hp:pageBorderFill type="ODD" borderFillIDRef="1" textBorder="PAPER" headerInside="0" footerInside="0" fillArea="PAPER"><hp:offset left="1417" right="1417" top="1417" bottom="1417"/></hp:pageBorderFill></hp:secPr><hp:ctrl><hp:colPr id="" type="NEWSPAPER" layout="LEFT" colCount="1" sameSz="1" sameGap="0"/></hp:ctrl></hp:run>`;

  /* 본문 폭 170mm, 쪽 높이 270mm */
  const BODY_W = 170, BODY_H = 268;
  function photoSection(docs, bins){
    let body = '', first = true, n = 0;
    docs.forEach(doc => {
      doc.pages.forEach((pg, pi) => {
        const pre = first ? SECPR : '';
        body += para(doc.sub || '', PP.center, CP.sub, { pre, pageBreak: !first });
        first = false;
        body += para(doc.title || '사진자료', PP.center, CP.title);
        /* 정보 표: 라벨 22mm | 값 | 라벨 22mm | 값 */
        const L = 22, V = (BODY_W - 2 * L) / 2;
        const infoRows = doc.info.map(r => r.length === 2
          ? [{ w: u(L), inner: para(r[0], PP.center, CP.label), bf: BF.gray }, { w: u(BODY_W - L), cs: 3, inner: para(r[1], PP.left, CP.text) }]
          : [{ w: u(L), inner: para(r[0], PP.center, CP.label), bf: BF.gray }, { w: u(V), inner: para(r[1], PP.left, CP.text) }, { w: u(L), inner: para(r[2], PP.center, CP.label), bf: BF.gray }, { w: u(V), inner: para(r[3], PP.left, CP.text) }]);
        /* 첫 줄 폭 기준이 4칸이어야 하므로 2칸 줄만 있는 경우를 대비해 첫 줄을 4칸으로 */
        body += tablePara(table(infoRows, infoRows.map(() => u(7.5)), 4));
        /* 사진 칸: 사진 줄 + 이름 줄을 번갈아 */
        const items = pi === doc.pages.length - 1 && doc.items && doc.items.rows.length ? doc.items : null;
        const itemsH = items ? (items.rows.length + 1) * 6.5 + 4 : 0;
        const capH = 6.5, fixed = 6 + 11 + doc.info.length * 7.5 + 3 + 7 + itemsH;
        const cellH = Math.max(30, (BODY_H - fixed) / pg.rows - capH);
        const cw = BODY_W / pg.cols;
        const rows = [], hs = [];
        for (let r = 0; r < pg.rows; r++){
          const pr = [], cr = [];
          for (let c = 0; c < pg.cols; c++){
            const p = pg.photos[r * pg.cols + c];
            let inner = para('', PP.pic, CP.cap);
            if (p) {
              const bin = 'image' + (++n); bins.push({ id: bin, bytes: p.bytes, ext: p.ext });
              const maxW = cw - 3, maxH = cellH - 3, k = Math.min(maxW / p.w, maxH / p.h);
              inner = `<hp:p id="0" paraPrIDRef="${PP.pic}" styleIDRef="0" pageBreak="0" columnBreak="0" merged="0"><hp:run charPrIDRef="${CP.cap}">${pic(bin, p.w, p.h, u(p.w * k), u(p.h * k))}<hp:t/></hp:run></hp:p>`;
            }
            pr.push({ w: u(cw), inner });
            cr.push({ w: u(cw), inner: para(p ? p.caption || '' : '', PP.center, CP.cap) });
          }
          rows.push(pr, cr); hs.push(u(cellH), u(capH));
        }
        body += tablePara(table(rows, hs, pg.cols));
        if (items) {
          const ws = items.widths || items.head.map(() => BODY_W / items.head.length);
          const tr = [items.head.map((h, k) => ({ w: u(ws[k]), inner: para(h, PP.center, CP.label), bf: BF.gray }))]
            .concat(items.rows.map(r => r.map((v, k) => ({ w: u(ws[k]), inner: para(v, k === 0 ? PP.left : (items.num || [])[k] ? PP.right : PP.center, CP.cap) }))));
          body += tablePara(table(tr, tr.map(() => u(6.5)), items.head.length));
        }
        body += para(doc.foot || '칼퇴상사', PP.right, CP.foot);
      });
    });
    return `${H_PO}xml version="1.0" encoding="UTF-8" standalone="yes" ${H_PC}<hs:sec ${NS}>${body}</hs:sec>`;
  }
  const NS = `xmlns:ha="${H_HT}www.hancom.co.kr/hwpml/2011/app" xmlns:hp="${H_HT}www.hancom.co.kr/hwpml/2011/paragraph" xmlns:hp10="${H_HT}www.hancom.co.kr/hwpml/2016/paragraph" xmlns:hs="${H_HT}www.hancom.co.kr/hwpml/2011/section" xmlns:hc="${H_HT}www.hancom.co.kr/hwpml/2011/core" xmlns:hh="${H_HT}www.hancom.co.kr/hwpml/2011/head" xmlns:hhs="${H_HT}www.hancom.co.kr/hwpml/2011/history" xmlns:hm="${H_HT}www.hancom.co.kr/hwpml/2011/master-page" xmlns:hpf="${H_HT}www.hancom.co.kr/schema/2011/hpf" xmlns:dc="${H_HT}purl.org/dc/elements/1.1/" xmlns:opf="${H_HT}www.idpf.org/2007/opf/" xmlns:ooxmlchart="${H_HT}www.hancom.co.kr/hwpml/2016/ooxmlchart" xmlns:hwpunitchar="${H_HT}www.hancom.co.kr/hwpml/2016/HwpUnitChar" xmlns:epub="${H_HT}www.idpf.org/2007/ops" xmlns:config="urn:oasis:names:tc:opendocument:xmlns:config:1.0"`;

  const MIME = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png' };
  /* 압축 없는 zip — 한글 규칙대로 mimetype이 맨 앞 */
  const CRC = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++){ let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
  const crc32 = b => { let c = 0xFFFFFFFF; for (let i = 0; i < b.length; i++) c = CRC[(c ^ b[i]) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
  function zip(files){
    const enc = new TextEncoder(), parts = [], cent = []; let off = 0;
    const le = (n, k) => { const a = new Uint8Array(k); for (let i = 0; i < k; i++) a[i] = (n >>> (8 * i)) & 0xFF; return a; };
    const cat = arr => { const n = arr.reduce((a, b) => a + b.length, 0), o = new Uint8Array(n); let p = 0; arr.forEach(b => { o.set(b, p); p += b.length; }); return o; };
    files.forEach(([p, d]) => {
      const name = enc.encode(p), data = typeof d === 'string' ? enc.encode(d) : d, crc = crc32(data);
      const local = cat([le(0x04034b50, 4), le(20, 2), le(0x0800, 2), le(0, 2), le(0, 2), le(0x21, 2), le(crc, 4), le(data.length, 4), le(data.length, 4), le(name.length, 2), le(0, 2), name]);
      parts.push(local, data);
      cent.push(cat([le(0x02014b50, 4), le(20, 2), le(20, 2), le(0x0800, 2), le(0, 2), le(0, 2), le(0x21, 2), le(crc, 4), le(data.length, 4), le(data.length, 4), le(name.length, 2), le(0, 2), le(0, 2), le(0, 2), le(0, 2), le(0, 4), le(off, 4), name]));
      off += local.length + data.length;
    });
    const cd = cat(cent);
    return cat([...parts, cd, le(0x06054b50, 4), le(0, 2), le(0, 2), le(files.length, 2), le(files.length, 2), le(cd.length, 4), le(off, 4), le(0, 2)]);
  }
  function photoDoc(docs, title){
    seq = 1000000 + Math.floor(Math.random() * 1000) * 1000;
    const bins = [], section = photoSection(docs, bins);
    return build(section, bins, title || '사진자료');
  }
  function build(section, bins, title){
    const manifest = bins.map(b => `<opf:item id="${b.id}" href="BinData/${b.id}.${b.ext}" media-type="${MIME[b.ext] || 'image/jpeg'}" isEmbeded="1"/>`).join('');
    const hpf = `${H_PO}xml version="1.0" encoding="UTF-8" standalone="yes" ${H_PC}<opf:package ${NS} version="" unique-identifier="" id=""><opf:metadata><opf:title>${esc(title)}</opf:title><opf:language>ko</opf:language></opf:metadata><opf:manifest><opf:item id="header" href="Contents/header.xml" media-type="application/xml"/>${manifest}<opf:item id="section0" href="Contents/section0.xml" media-type="application/xml"/><opf:item id="settings" href="settings.xml" media-type="application/xml"/></opf:manifest><opf:spine><opf:itemref idref="header" linear="yes"/><opf:itemref idref="section0" linear="yes"/></opf:spine></opf:package>`;
    const files = [
      ['mimetype', 'application/hwp+zip'],
      ['version.xml', '' + H_PO + 'xml version="1.0" encoding="UTF-8" standalone="yes" ' + H_PC + `<hv:HCFVersion xmlns:hv="${H_HT}www.hancom.co.kr/hwpml/2011/version" tagetApplication="WORDPROCESSOR" major="5" minor="1" micro="1" buildNumber="0" os="1" xmlVersion="1.5" application="Hancom Office Hangul" appVersion="13, 0, 0, 711 WIN32LEWindows_10"/>`],
      ['Contents/header.xml', HEADER],
      ['Contents/section0.xml', section],
      ['settings.xml', '' + H_PO + 'xml version="1.0" encoding="UTF-8" standalone="yes" ' + H_PC + `<ha:HWPApplicationSetting xmlns:ha="${H_HT}www.hancom.co.kr/hwpml/2011/app" xmlns:config="urn:oasis:names:tc:opendocument:xmlns:config:1.0"><ha:CaretPosition listIDRef="0" paraIDRef="0" pos="0"/></ha:HWPApplicationSetting>`],
      ['META-INF/container.xml', '' + H_PO + 'xml version="1.0" encoding="UTF-8" standalone="yes" ' + H_PC + `<ocf:container xmlns:ocf="urn:oasis:names:tc:opendocument:xmlns:container" xmlns:hpf="${H_HT}www.hancom.co.kr/schema/2011/hpf"><ocf:rootfiles><ocf:rootfile full-path="Contents/content.hpf" media-type="application/hwpml-package+xml"/></ocf:rootfiles></ocf:container>`],
      ['META-INF/manifest.xml', '' + H_PO + 'xml version="1.0" encoding="UTF-8" standalone="yes" ' + H_PC + '<odf:manifest xmlns:odf="urn:oasis:names:tc:opendocument:xmlns:manifest:1.0"/>'],
      ['Contents/content.hpf', hpf]
    ].concat(bins.map(b => ['BinData/' + b.id + '.' + b.ext, b.bytes]));
    return zip(files);
  }

  /* 일반 문서: 문단과 표를 순서대로. blocks: [{ k:'p', t, align:'left|center|right', style:'title|sub|text|label|cap|foot' }
       | { k:'table', widths:[mm…], rows:[[{ t, gray, cs, rs, align, style }]], h: 줄 높이 mm 또는 [mm…] } | { k:'break' }]
       rs = 세로 병합(줄 수). 병합된 아래 줄에서는 그 칸을 빼고 적는다. 칸 폭은 widths 순서대로 — rs 칸이 차지한 열은 아래 줄에서 자동으로 건너뜀
     글자 안 줄바꿈(\n)은 문단 나눔 */
  /* opt: { bodyW: 본문 폭 mm, landscape: 가로 쪽 } */
  function textDoc(blocks, title, opt){
    seq = 1000000 + Math.floor(Math.random() * 1000) * 1000;
    const W = (opt && opt.bodyW) || BODY_W;
    const al = a => a === 'center' ? PP.center : a === 'right' ? PP.right : PP.left;
    const st = x => CP[x] || CP.text;
    const multi = (t, pp, cp) => String(t == null ? '' : t).split('\n').map(line => para(line, pp, cp)).join('');
    let body = '', first = true, pending = false;
    /* opt.landscape: A4 가로 (본문 폭 257mm 권장). 한글은 width·height가 실제 쪽 크기이고 landscape 깃발은 WIDELY 그대로 — NARROWLY로 바꾸면 한 번 더 돌아 세로가 됨 (2026-10-10 확인) */
    const sec = opt && opt.landscape ? SECPR.replace('landscape="WIDELY" width="59528" height="84186"', 'landscape="WIDELY" width="84186" height="59528"') : SECPR;
    const pre = () => { const p = first ? sec : ''; first = false; return p; };
    blocks.forEach(b => {
      if (b.k === 'break') { pending = true; return; }
      if (b.k === 'table') {
        const ws = b.widths || b.rows[0].map(() => W / b.rows[0].length);
        const busy = {};
        const rows = b.rows.map(r => { let c = 0; const out = r.map(cell => { while (busy[c] > 0) c++; const w = ws.slice(c, c + (cell.cs || 1)).reduce((a, x) => a + x, 0); if (cell.rs > 1) for (let k = 0; k < (cell.cs || 1); k++) busy[c + k] = cell.rs; c += cell.cs || 1;
          return { w: u(w), cs: cell.cs, rs: cell.rs, bf: cell.gray ? BF.gray : BF.line, inner: multi(cell.t, al(cell.align || (cell.gray ? 'center' : 'left')), st(cell.style || (cell.gray ? 'label' : 'cap'))) }; }); Object.keys(busy).forEach(k => { if (busy[k] > 0) busy[k]--; }); return out; });
        const hs = b.rows.map((r, i) => u(Array.isArray(b.h) ? b.h[i] : (b.h || 7)));
        body += tablePara(table(rows, hs, ws.length, { flow: true }), { pre: pre(), pageBreak: pending }); pending = false;
        return;
      }
      const p = pre(), lines = String(b.t == null ? '' : b.t).split('\n');
      lines.forEach((line, i) => { body += para(line, al(b.align), st(b.style), { pre: i === 0 ? p : '', pageBreak: i === 0 && pending }); });
      pending = false;
    });
    const section = `${H_PO}xml version="1.0" encoding="UTF-8" standalone="yes" ${H_PC}<hs:sec ${NS}>${body}</hs:sec>`;
    return build(section, [], title || '문서');
  }
  return { photoDoc, textDoc, zip };
})();

